//! B27S block framing: magic, repeated u32 BE frame length + B27N, zero terminator.
use std::io::{Read,Write};
pub const BLOCK:usize=256*1024;
pub fn encode(mut r:impl Read,mut w:impl Write,mode:u8)->std::io::Result<()> {w.write_all(b"B27S")?;let mut b=vec![0;BLOCK];loop{let mut n=0;while n<BLOCK{let k=r.read(&mut b[n..])?;if k==0{break}n+=k}if n==0{break}let frame=crate::compress(&b[..n],mode).map_err(std::io::Error::other)?;w.write_all(&(frame.len()as u32).to_be_bytes())?;w.write_all(&frame)?;}w.write_all(&[0;4])}
pub fn decode(mut r:impl Read,mut w:impl Write,max:u64)->std::io::Result<()> {let mut h=[0;4];r.read_exact(&mut h)?;if &h!=b"B27S"{return Err(std::io::Error::other("magic"))}let mut total=0u64;loop{r.read_exact(&mut h)?;let n=u32::from_be_bytes(h)as usize;if n==0{let mut x=[0];if r.read(&mut x)?!=0{return Err(std::io::Error::other("trailing data"))}return Ok(())}if !(41..=BLOCK*15+4096).contains(&n){return Err(std::io::Error::other("frame limit"))}let mut b=vec![0;n];r.read_exact(&mut b)?;if &b[..4]!=b"B27N"||u32::from_be_bytes(b[5..9].try_into().unwrap())as usize>BLOCK{return Err(std::io::Error::other("block limit"))}let p=crate::decompress(&b).map_err(std::io::Error::other)?;total+=p.len()as u64;if total>max{return Err(std::io::Error::other("output limit"))}w.write_all(&p)?}}
